import {AnalyticsProvider} from '@github-ui/analytics-provider'
import {ContextualGlobalSsoBanner} from '@github-ui/global-sso-banner/contextual'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {Outlet, useNavigation} from '@github-ui/react-router'
import {ReposFilter} from '@github-ui/repos-filter'
import {ReposShortcutSidebar} from '@github-ui/repos-list'
import {ShortcutEditingHeader} from '@github-ui/saved-views'
import {PageLayout} from '@primer/react'

import {FinderHeader} from '../components/FinderHeader'
import {FinderSidebar} from '../components/FinderSidebar'
import {ReposFinderStateProvider, useReposFinderStateContext} from '../contexts/ReposFinderStateContext'
import {useReposFinderLayoutState} from '../hooks/use-repos-finder-layout-state'
import {reposFinderLayoutRoute} from './repos-finder-layout-route'

export function ReposFinderLayoutEntrypoint() {
  const {data: payload} = useRouteQuery(reposFinderLayoutRoute, 'mainQuery')
  return (
    <AnalyticsProvider appName="repos-finder-page" category="Finder page" metadata={{page: 'repos-finder'}}>
      <ContextualGlobalSsoBanner />
      <ReposFinderStateProvider payload={payload}>
        <ReposFinderLayout />
      </ReposFinderStateProvider>
    </AnalyticsProvider>
  )
}

function ReposFinderLayout() {
  const {shortcuts, selectedSidebarItem, editing, deleting, methods, reposFilterProps} = useReposFinderLayoutState()
  const {fetchedQuery} = useReposFinderStateContext()
  const {state: navigationState} = useNavigation()

  const isLoading = navigationState === 'loading'

  return (
    <PageLayout containerWidth="full" columnGap="none" padding="none">
      <PageLayout.Pane
        divider="line"
        hidden={{narrow: true, regular: false, wide: false}}
        padding="condensed"
        position="start"
        className="min-height-full"
      >
        <aside>
          <FinderSidebar type={selectedSidebarItem?.id || ''} onSelectLink={methods.selectSidebarLink} />
          <ReposShortcutSidebar
            shortcuts={shortcuts}
            onSelectLink={methods.selectSidebarLink}
            selectedLink={selectedSidebarItem?.id || ''}
            onCreateView={methods.createShortcut}
          />
        </aside>
      </PageLayout.Pane>

      <PageLayout.Content as="div" padding="condensed" className="px-2 mx-auto" style={{maxWidth: '1400px'}}>
        {editing.shortcut ? (
          <ShortcutEditingHeader
            renderFilter={filterProps => <ReposFilter {...filterProps} {...reposFilterProps} />}
            onSave={editing.saveAndDismiss}
            onDismiss={editing.dismiss}
            shortcut={editing.shortcut}
            setShortcutValue={editing.setValue}
            isSaving={editing.isSaving}
            errorMessage={editing.errorMessage}
          />
        ) : (
          <FinderHeader
            selectedSidebarItem={selectedSidebarItem}
            reposFilterProps={reposFilterProps}
            shortcuts={shortcuts}
            onSelectLink={methods.selectSidebarLink}
            onCreateView={methods.createShortcut}
            onDeleteView={deleting.deleteShortcut}
            onEditView={methods.editShortcut}
            onUpdateQueryView={methods.updateShortcut}
            isQueryModified={!isLoading && fetchedQuery !== selectedSidebarItem?.query}
            deleteErrorMessage={deleting.errorMessage}
          />
        )}
        <Outlet />
      </PageLayout.Content>
    </PageLayout>
  )
}
